//! Almanac's data model and sync protocol.
//!
//! The server uses these types directly. The clients get them as TypeScript,
//! generated by `bun run gen:types` into `packages/types`.
//!
//! Everything a workspace keeps syncs: its topics, their blocks, points, reminders
//! and questions, the talks they were kept from, and its members.
//!
//! On the wire, field names are snake_case, the same as the database columns.

mod account;
mod model;
mod protocol;
mod talk;
mod topic;
mod user;

pub use account::{
    ClaudeCodeInfo, ClaudeKeyInfo, Me, MemberInfo, ReadToken, ReadTokenInfo, Role,
    SetAnswersRequest, SetClaudeKeyRequest, SetClaudeWebRequest, UpdateMemberRequest,
    UpdateProfileRequest, UpdateWorkspaceRequest, UserInfo, WorkspaceInfo, clean_name,
    normalize_email, url_key_from,
};
pub use model::{Actor, ModelKind, Validate, ValidationError, Write};
pub use protocol::{
    ApiError, Bootstrap, Operation, ServerMessage, SyncAction, SyncEntry, Transaction,
    TransactionResult,
};
pub use talk::{
    Answered, AskRequest, BlockWas, HandedPhoto, HandedQuestion, LayoutMove, Message,
    MessageCreate, MessagePatch, NotAnswered, PageLayout, Photo, PhotoUpload, PointWas, Proposal,
    ProposedPoint, ProposedReminder, Source, Talk, TalkCreate, TalkPatch, TopicChange,
};
pub use topic::{
    BLOCK_VIEWS, BLOCK_WIDTHS, Block, BlockCreate, BlockPatch, Cell, FACET_ICONS, FIELD_KINDS,
    Facet, Field, ICONS, KINDS, LOOKS, MOST_FACETS, MOST_FIELDS, PICTURE_CELL, Point, PointCreate,
    PointPatch, Question, QuestionCreate, QuestionPatch, Reminder, ReminderCreate, ReminderPatch,
    SET_KINDS, STICKS_TO_MAX, StartTopicRequest, StartedTopic, TEMPLATE_NAMES, TEMPLATES, Topic,
    TopicCreate, TopicPatch, template,
};
pub use user::User;
